def main():
    protected={}
    def read(p):protected[p.relative_to(GAME).as_posix()]=sha(p);return json.loads(p.read_text(encoding='utf-8-sig'))
    p=ROOT/'src/data/feats.js';raw=json.JSONDecoder().raw_decode(p.read_text(encoding='utf-8-sig').split('export const feats = ',1)[1])[0];protected[p.relative_to(GAME).as_posix()]=sha(p);by={z['id']:z for z in raw}
    reviewed=set(read(ROOT/'data/public/feat_playtests/manifest.json')['operationalIds']);routed={z['featId'] for n in ['CRAFTING_FEAT_INTERFACE','COMBAT_FEAT_SOURCE','SKILL_FEAT_SOURCE','MAGIC_CORE_FEAT_SOURCE','MAGIC_EXTENDED_FEAT_SOURCE','HERITAGE_MUTATION_FEAT_SOURCE','GENERAL_DEFENSE_FEAT_SOURCE'] for z in read(AUDIT/(n+'_PREPARATION.json'))['selectedFeats']};pending=read(AUDIT/'REMAINING_FEAT_CATALOG_PREPARATION.json')
    selected=[x for x in raw if x['id'] in QUESTIONS];assert len(selected)==31 and len(routed)==238 and set(QUESTIONS).isdisjoint(routed|reviewed)
    counterparts=[{'sourceObject':by[id],'operationalReviewed':id in reviewed,'scope':'dependency only; no merger or approval'} for id in COUNTERPARTS]
    excerpts=[]
    for name,heads in CONTEXT.items():
        p=ROOT/'docs/mechanics'/name;t=p.read_text(encoding='utf-8');protected[p.relative_to(GAME).as_posix()]=sha(p)
        for h in heads:excerpts.append({'file':p.relative_to(GAME).as_posix(),'sha256':sha(p),'heading':h,'exactText':section(t,h)})
    equipment=read(ROOT/'data/playtest/equipment_acquisition_candidate.json');items=[z for z in equipment['items'] if z['name'] in ("Cartographer's tools",'Rations (1 day)','Waterskin',"Navigator's tools")]
    rows=[{'featId':x['id'],'questionId':f'GE-{i+1:02}','sourceObject':x,'sourceObjectSha256':digest(x),'fullClauseQuestion':QUESTIONS[x['id']],'currentOperationalStatus':'full-feat-review-pending'} for i,x in enumerate(selected)]
    checks=[('335 source registry byte equality',len(raw)==335 and (ROOT/'src/data/feats.js').read_bytes()==(GAME/'src/data/feats.js').read_bytes()),('327 full pending source records preserved',[x for x in raw if x['id'] not in reviewed]==[z['sourceObject'] for z in pending['records']]),('31 distinct General sources and questions',len(rows)==31 and all(z['sourceObject']['type']=='General' and len(z['fullClauseQuestion'])>150 for z in rows)),('No overlap with238 prepared or8 reviewed',set(QUESTIONS).isdisjoint(routed|reviewed)),('Sixteen counterpart sources exact',len(counterparts)==16 and all(z['sourceObject']==by[z['sourceObject']['id']] for z in counterparts)),('All source hashes and governing excerpts exact',all(z['sourceObjectSha256']==digest(z['sourceObject']) for z in rows) and all(z['exactText'] in (GAME/z['file']).read_text(encoding='utf-8') for z in excerpts)),('58 pending General identities remain',len([x for x in raw if x['id'] not in reviewed|routed|set(QUESTIONS)])==58),('Protected input preservation',all(sha(GAME/q)==h for q,h in protected.items()))]
    assert all(v for _,v in checks),[n for n,v in checks if not v]
    counts={'sourceFeats':335,'operationalReviewed':8,'pending':327,'selectedGeneralExploration':31,'counterparts':16,'governingExcerpts':len(excerpts),'equipmentRecords':len(items),'pendingSourcePrepared':269,'otherPendingFocusedPreparation':58}
    data={'status':'prepared-not-sent; source questions only','sourceFileSha256':sha(ROOT/'src/data/feats.js'),'selectedFeats':rows,'counterpartSources':counterparts,'currentEquipmentMatches':items,'currentGoverningExcerpts':excerpts,'largerSystemDependencies':'Complete travel,foraging,Supply,reputation,hirelings,social access and economy interfaces remain open; existing excerpts are not blanket domain approval. Require actual source work on those dependencies before finalizing affected feat choices.','counts':counts,'checks':[{'name':n,'pass':v} for n,v in checks],'protectedFiles':protected,'featsApproved':0,'newRules':False,'sourceInformationDeleted':0,'cosmology':'post-push only'}
    dump(AUDIT/'GENERAL_EXPLORATION_FEAT_SOURCE_PREPARATION.json',data)
    lines=['# General exploration, social and training feat sources','',data['status'],'','Thirty-one complete originals and full-clause questions preserve proficiency/expertise,appraisal,travel,tracking,survival and social clauses. Related names remain distinct identities. Absolute language such as never lost,any item,any environment andtracking through air requires an explicit decision rather than automatic omniscience or free resources.','',data['largerSystemDependencies'],'','| Case | Source feat | Full-clause decision |','|---|---|---|']
    lines += [f"| {z['questionId']} | {z['sourceObject']['name']} ({z['featId']}) | {z['fullClauseQuestion']} |" for z in rows]
    lines+=['','This packet remains unsent while Jewelcrafting exact review runs. Pending feat sources prepared269; remaining58 General identities still need focused preparation. Eight feats remain operationally reviewed. No source deletion, gameplay change or cosmology decision.',''];audit='\n'.join(lines);write(AUDIT/'GENERAL_EXPLORATION_FEAT_SOURCE_AUDIT.md',audit)
    packet='\n\n'.join(['PREPARED GENERAL EXPLORATION/SOCIAL/TRAINING CONFERENCE — NOT SENT.31 complete sources and full-clause questions with current governing evidence. No identity merge, new effect, availability grant or approval. Larger exploration/economy dependencies and cosmology remain explicitly open.',audit,'COMPLETE SOURCE AND GOVERNING EVIDENCE',json.dumps(data,ensure_ascii=False,separators=(',',':'))]);p=AUDIT/'CODEX_GENERAL_EXPLORATION_FEAT_SOURCE_PREPARED.txt';write(p,packet)
    status={'status':'prepared-not-sent','packetFile':p.name,'characters':len(packet),'packetSha256':sha(p),'counts':counts,'checkCount':len(checks),'protectedFilesUnchanged':len(protected),'featsApproved':0,'sourceInformationDeleted':0,'cosmology':'post-push only'};dump(AUDIT/'GENERAL_EXPLORATION_FEAT_SOURCE_STATUS.json',status);print(json.dumps(status))

